import { expect, expectStatus, test } from "../../fixtures";

test("Fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt", "member");

  // Act: extraction runs in the background, so wait for the document to leave "processing".
  await expect
    .poll(
      async () => {
        const doc = await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200);
        return doc.status;
      },
      { message: "processing finishes for the insurance certificate", timeout: 30_000 },
    )
    .toBe("extracted");

  const extraction = await expectStatus<{
    fields: Record<string, { value: string | null; confidence: number }>;
  }>(await member.get(`/api/documents/${document.id}/extraction`), 200);

  // Assert: the stored extraction, not just a response, shows the unparseable expiry date.
  const expiry = extraction.fields["expiry_date"];
  expect(expiry, "expiry_date field is present").toBeDefined();
  expect(expiry.value, "expiry_date value is null").toBeNull();
  expect(expiry.confidence, "expiry_date confidence is below 0.5").toBeLessThan(0.5);
});
